// IT 직종 키워드 목록
const keywords = ['백엔드개발자', '프론트엔드개발자', '풀스택개발자', '데이터엔지니어', '머신러닝엔지니어'];
return keywords.map(kw => ({ json: { keyword: kw } }));

// XML 파싱 (n8n 내장 XML 파서 활용)
const xml = $input.all()[0].json.data || $input.all()[0].json;
const xmlStr = typeof xml === 'string' ? xml : JSON.stringify(xml);

// 간단한 XML → JSON 변환
function parseXmlField(xmlStr, tag) {
  const regex = new RegExp(`<${tag}>(.*?)</${tag}>`, 'gs');
  const matches = [];
  let m;
  while ((m = regex.exec(xmlStr)) !== null) {
    matches.push(m[1].trim());
  }
  return matches;
}

const wantedAuthNos = parseXmlField(xmlStr, 'wantedAuthNo');
const corps        = parseXmlField(xmlStr, 'corp');
const titles       = parseXmlField(xmlStr, 'wantedTitle');
const regions      = parseXmlField(xmlStr, 'region1Nm');
const empTps       = parseXmlField(xmlStr, 'empTpNm');
const sals         = parseXmlField(xmlStr, 'sal');
const salTps       = parseXmlField(xmlStr, 'salTpNm');
const regDts       = parseXmlField(xmlStr, 'regDt');
const closeDts     = parseXmlField(xmlStr, 'closeDt');
const jobsNms      = parseXmlField(xmlStr, 'jobsNm');
const minEdus      = parseXmlField(xmlStr, 'minEdubgNm');
const careers      = parseXmlField(xmlStr, 'career');
const urls         = parseXmlField(xmlStr, 'wantedInfoUrl');

const jobs = wantedAuthNos.map((id, i) => ({
  wantedAuthNo: id,
  corp:         corps[i]    || '',
  wantedTitle:  titles[i]   || '',
  region1Nm:    regions[i]  || '',
  empTpNm:      empTps[i]   || '',
  sal:          sals[i]     || '',
  salTpNm:      salTps[i]   || '',
  regDt:        regDts[i]   || '',
  closeDt:      closeDts[i] || '',
  jobsNm:       jobsNms[i]  || '',
  minEdubgNm:   minEdus[i]  || '',
  career:       careers[i]  || '',
  wantedInfoUrl: urls[i]    || '',
  source:       'goyo24',
}));

return [{ json: { jobs } }];

const r = $input.all()[0].json;
console.log(`✅ 고용24: ${r.saved}개 저장, ${r.skipped}개 스킵`);
return [{ json: r }];
